package com.overhead;

import java.awt.*;
import java.awt.image.BufferedImage;

import javax.inject.Inject;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Slf4j
public class OverheadOverlay extends Overlay
{

    private final Client client;
    private final OverheadPlugin plugin;
    private final OverheadConfig config;

    @Inject
    public OverheadOverlay(Client client, OverheadPlugin plugin, OverheadConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setMovable(false);
        setLayer(OverlayLayer.UNDER_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {

        if(plugin.activePrayers.isEmpty()){ // no prayers active. Don't waste compute.
            return null;
        }

        Player player = client.getLocalPlayer();


        LocalPoint lp = player.getLocalLocation();

        int groundHeight = Perspective.getFootprintTileHeight(
                client,
                player.getLocalLocation(),
                client.getPlane(),
                player.getFootprintSize()
        );
        // Adjust height in 3D space
        int zOffset = player.getLogicalHeight()+24; // tweak this

        Point point = Perspective.localToCanvas(
                client,
                player.getLocalLocation().getX(),
                player.getLocalLocation().getY(),
                groundHeight - zOffset
        );

        boolean isSkulled = client.getLocalPlayer().getSkullIcon() != -1;

        if (point == null)
            return null;

        boolean isOverheadActive = player.getOverheadIcon() != null;
        boolean isOverheadTextActive = player.getOverheadText() != null;

        if(config.iconSize() == OverheadConfig.PrayerIconSize.BIG) {

            int[] overheadActivePattern = new int[]{-30, +30, -60, +60, -90, +90, -120, +120};
            int[] noOverheadAndEvenPattern = new int[]{-15, +15, -45, +45, -75, +75, -105, +105};
            int[] noOverheadAndOddPattern = new int[]{0, -30, +30, -60, +60, -90, +90, -120, +120};

            int[] chosenPattern = null;

            if (isOverheadActive) {
                chosenPattern = overheadActivePattern;
            } else if (plugin.activePrayers.size() % 2 == 0) {
                chosenPattern = noOverheadAndEvenPattern;
            } else {
                chosenPattern = noOverheadAndOddPattern;
            }


            for (int i = 0; i < plugin.activePrayers.size(); i++) {
                Prayer prayer = plugin.activePrayers.get(i);
                BufferedImage image = plugin.prayerImages.get(prayer)[0];

                int yOffset = 0;
                if (isSkulled) {
                    yOffset = -28;
                }

                // Chat text changes the overhead offset.
                if (isOverheadTextActive) {
                    yOffset = yOffset - 5;
                }

                int offset = chosenPattern[i];
                graphics.drawImage(
                        image,
                        point.getX() - image.getWidth() / 2 + offset,
                        point.getY() - 30 - 2 + yOffset,
                        null
                );

            }
        }else if(config.iconSize() == OverheadConfig.PrayerIconSize.SMALL){

            if(isOverheadActive) {
                int[][][] overheadActivePattern = {
                        {{-7, 0}},                    // if only 1 prayer
                        {{-7, 0}, {7, 0}},        // if only 2 prayers
                        {{-7, -8}, {-7, 8}, {7, 0}},
                        {{-7, -8}, {-7, 8}, {7, -8}, {7, 8}}
                };

                int[][] chosenPattern = null;

                    chosenPattern = overheadActivePattern[plugin.activePrayers.size() - 1];


                    for (int i = 0; i < chosenPattern.length; i++) {

                        int yOffset = 0;
                        if (isSkulled) {
                            yOffset = -28;
                        }

                        // Chat text changes the overhead offset.
                        if (isOverheadTextActive) {
                            yOffset = yOffset - 5;
                        }


                        int[] offsets = chosenPattern[i];
                        Prayer prayer = plugin.activePrayers.get(i);
                        BufferedImage image = plugin.prayerImages.get(prayer)[2];

                        graphics.drawImage(
                                image,
                                point.getX() - image.getWidth() / 2 + offsets[0] * 4,
                                point.getY() + image.getHeight() / 2 - 30 + offsets[1] + yOffset,
                                null
                        );

                    }

            }else{
                int[][][] overheadActivePattern = {
                        {{0, 0}},                    // if only 1 prayer
                        {{-8, 0}, {8, 0}},        // if only 2 prayers
                        {{-8, -8}, {-8, 8}, {8, -8}},
                        {{-8, -8}, {-8, 8}, {8, -8}, {8, 8}}
                };

                int[][] chosenPattern = null;

                    chosenPattern = overheadActivePattern[plugin.activePrayers.size() - 1];

                    for (int i = 0; i < chosenPattern.length; i++) {

                        int yOffset = 0;
                        if (isSkulled) {
                            yOffset = -28;
                        }

                        // Chat text changes the overhead offset.
                        if (isOverheadTextActive) {
                            yOffset = yOffset - 5;
                        }

                        int[] offsets = chosenPattern[i];
                        Prayer prayer = plugin.activePrayers.get(i);
                        BufferedImage image = plugin.prayerImages.get(prayer)[2];

                        graphics.drawImage(
                                image,
                                point.getX() - image.getWidth() / 2 + offsets[0],
                                point.getY() + image.getHeight() / 2 - 30 + offsets[1] + yOffset,
                                null
                        );

                    }


            }
        } else if(config.iconSize() == OverheadConfig.PrayerIconSize.MEDIUM){

            if(isOverheadActive) {
                int[][][] overheadActivePattern = {
                        {{-10, 0}},                    // if only 1 prayer
                        {{-10, 0}, {10, 0}},        // if only 2 prayers
                        {{-10, -10}, {-10, 10}, {10, 0}},
                        {{-10, -10}, {-10, 10}, {10, -10}, {10, 10}}
                };

                int[][] chosenPattern = null;

                    chosenPattern = overheadActivePattern[plugin.activePrayers.size() - 1];


                    for (int i = 0; i < chosenPattern.length; i++) {
                        int yOffset = 0;
                        if (isSkulled) {
                            yOffset = -28;
                        }

                        // Chat text changes the overhead offset.
                        if (isOverheadTextActive) {
                            yOffset = yOffset - 5;
                        }


                        int[] offsets = chosenPattern[i];
                        Prayer prayer = plugin.activePrayers.get(i);
                        BufferedImage image = plugin.prayerImages.get(prayer)[1];

                        graphics.drawImage(
                                image,
                                point.getX() - image.getWidth() / 2 + offsets[0] * 3,
                                point.getY() + image.getHeight() / 2 - 40 + offsets[1]+yOffset,
                                null
                        );

                    }

            }else{
                int[][][] overheadActivePattern = {
                        {{0, 0}},                    // if only 1 prayer
                        {{-11, 0}, {11, 0}},        // if only 2 prayers
                        {{-11, -10}, {-11, 10}, {11, -10}},
                        {{-11, -10}, {-11, 10}, {11, -10}, {11, 10}}
                };

                int[][] chosenPattern = null;

                    chosenPattern = overheadActivePattern[plugin.activePrayers.size() - 1];

                    for (int i = 0; i < chosenPattern.length; i++) {
                        int yOffset = 0;
                        if (isSkulled) {
                            yOffset = -28;
                        }

                        // Chat text changes the overhead offset.
                        if (isOverheadTextActive) {
                            yOffset = yOffset - 5;
                        }

                        int[] offsets = chosenPattern[i];
                        Prayer prayer = plugin.activePrayers.get(i);
                        BufferedImage image = plugin.prayerImages.get(prayer)[1];

                        graphics.drawImage(
                                image,
                                point.getX() - image.getWidth() / 2 + offsets[0],
                                point.getY() + image.getHeight() / 2 - 40 + offsets[1]+yOffset,
                                null
                        );

                    }


            }
        }
        return null;
    }

}

